// Lineage property tests for jedisct1/rust-hmac-sha256 (recipe overlay, protected).
// Expected values were computed with Python's hashlib and hmac modules (an independent
// implementation) when the recipe was written: SHA-256 over messages of every length around the
// 64-byte block and padding boundaries, HMAC-SHA256 with keys shorter than, equal to and longer
// than the block, and RFC 5869 HKDF-SHA256 (extract and expand, up to the 255-block maximum).
// Inputs are a fixed byte pattern, so no data is embedded.
use hmac_sha256::{Hash, HKDF, HMAC};

fn msg(i: usize, n: usize) -> Vec<u8> {
    (0..n).map(|j| ((j * 31 + i * 7 + 13) & 0xff) as u8).collect()
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{:02x}", x)).collect()
}
