#[test]
fn sha256_one_shot() {
    for (k, &(n, want)) in HASHES.iter().enumerate() {
        assert_eq!(hex(&Hash::hash(&msg(k, n))), want, "length {}", n);
    }
}

#[test]
fn sha256_streaming_any_split() {
    for (k, &(n, want)) in HASHES.iter().enumerate() {
        let m = msg(k, n);
        for split in [0, 1, 7, 63, 64, 65, 130] {
            let mut h = Hash::new();
            let mut rest = &m[..];
            while !rest.is_empty() {
                let take = core::cmp::min(rest.len(), if split == 0 { rest.len() } else { split });
                h.update(&rest[..take]);
                rest = &rest[take..];
            }
            assert_eq!(hex(&h.finalize()), want, "length {} split {}", n, split);
        }
    }
}

#[test]
fn sha256_verify() {
    for (k, &(n, _)) in HASHES.iter().enumerate() {
        let m = msg(k, n);
        let d = Hash::hash(&m);
        assert!(Hash::verify(&m, &d));
        let mut bad = d;
        bad[(k * 5) % 32] ^= 1 << (k % 8);
        assert!(!Hash::verify(&m, &bad));
        let mut h = Hash::new();
        h.update(&m);
        assert!(h.verify_with_ref(&d[..]));
        let mut h = Hash::new();
        h.update(&m);
        assert!(!h.verify_with_ref(&d[..31]));
    }
}

#[test]
fn hmac_one_shot_and_streaming() {
    for &(kl, ml, k, want) in MACS {
        let key = msg(100 + k, kl);
        let m = msg(200 + k, ml);
        assert_eq!(hex(&HMAC::mac(&m, &key)), want, "key {} msg {}", kl, ml);
        let mut s = HMAC::new(&key);
        let (a, b) = m.split_at(ml / 3);
        s.update(a);
        s.update(b);
        let out = s.finalize();
        assert_eq!(hex(&out), want);
        assert!(HMAC::verify(&m, &key, &out));
        let mut bad = out;
        bad[0] ^= 0x80;
        assert!(!HMAC::verify(&m, &key, &bad));
    }
}

#[test]
fn hkdf_rfc5869() {
    for &(sl, il, nl, l, k, prk_want, okm_want) in HKDFS {
        let prk = HKDF::extract(msg(300 + k, sl), msg(400 + k, il));
        assert_eq!(hex(&prk), prk_want);
        let mut okm = vec![0u8; l];
        HKDF::expand(&mut okm, prk, msg(500 + k, nl));
        assert_eq!(hex(&okm), okm_want, "length {}", l);
    }
}
